-- Name: insert_sensor_data(integer, integer, integer, character varying, character varying, double precision, integer, integer, integer, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_sensor_data(_userid integer, _watchid integer, _phoneid integer, _sensorname character varying, _alertgiven character varying, _value double precision, _pulses integer, _intensity integer, _duration integer, _interval integer, _fbrangeid integer, _vibration_reason character varying DEFAULT NULL::character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  _usecaseID INT;
  _alertID INT;
  _assigned_usecase VARCHAR;
BEGIN
  -- Validate user's assigned use case matches incoming sensor name
  SELECT uc.name INTO _assigned_usecase
  FROM public."User" u
  JOIN public."UseCase" uc ON u.active_usecase_id = uc.usecase_id
  WHERE u.userid = _userid;

  IF _assigned_usecase IS NULL OR _assigned_usecase != _sensorname THEN
    RAISE NOTICE 'Rejected data for User %: Expected %, received %',
      _userid, _assigned_usecase, _sensorname;
    RETURN;
  END IF;

  -- Auto-register devices
    WHERE NOT EXISTS (SELECT 1 FROM "User" WHERE userID = _userID);
    WHERE NOT EXISTS (SELECT 1 FROM "Watch" WHERE watchID = _watchID);
    WHERE NOT EXISTS (SELECT 1 FROM "AndroidPhone" WHERE phoneID = _phoneID);
    SELECT _watchID, _phoneID
    WHERE NOT EXISTS (
      SELECT 1 FROM "WatchAndroidPhone"
      WHERE watchID = _watchID AND phoneID = _phoneID);
    SELECT _userID, _watchID, _phoneID
    WHERE NOT EXISTS (
      SELECT 1 FROM "UserWatchAndroidPhone"
      WHERE userID = _userID AND watchID = _watchID AND phoneID = _phoneID);

  -- Resolve usecase_id from UseCase table (replaces the old SensorType lookup)
  SELECT usecase_id INTO _usecaseID
  FROM "UseCase" WHERE name = _sensorname;

  IF _usecaseID IS NULL THEN
    RAISE NOTICE 'No UseCase found for name: %', _sensorname;
    RETURN;
  END IF;

                      type, fbRangeID, vibration_reason)
  VALUES (_alertGiven, _pulses, _intensity, _duration, _interval,
          _sensorname, _fbrangeid, _vibration_reason)
  RETURNING alertID INTO _alertID;

    SELECT _usecaseID, _userID, _watchID, _phoneID
    WHERE NOT EXISTS (
      SELECT 1 FROM "DeviceSensor"
      WHERE usecase_id = _usecaseID AND userID = _userID
        AND watchID = _watchID AND phoneID = _phoneID);

                            alertID, value, time)
  VALUES (_usecaseID, _userID, _watchID, _phoneID,
          _alertID, _value, CURRENT_TIMESTAMP);
END;
$$;


ALTER FUNCTION public.insert_sensor_data(_userid integer, _watchid integer, _phoneid integer, _sensorname character varying, _alertgiven character varying, _value double precision, _pulses integer, _intensity integer, _duration integer, _interval integer, _fbrangeid integer, _vibration_reason character varying) OWNER TO postgres;

--
-- TOC entry 243 (class 1255 OID 17610)
-- Name: resolve_fb_range(integer, character varying, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_fb_range(_userid integer, _sensorname character varying, _value double precision) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    _rangeid INT;
BEGIN
    -- 1. Try personalized rule for this user first
    SELECT id INTO _rangeid
    FROM public.feedback_config_rules
    WHERE active = true
      AND type   = _sensorname
      AND user_id = _userid
      AND (_value >= minvalue OR minvalue IS NULL)
      AND (_value <= maxvalue OR maxvalue IS NULL)
    ORDER BY user_id NULLS LAST   -- personalized before global
    LIMIT 1;
 
    -- 2. Fall back to global rule
    IF _rangeid IS NULL THEN
        SELECT id INTO _rangeid
        FROM public.feedback_config_rules
        WHERE active   = true
          AND type     = _sensorname
          AND user_id  IS NULL
          AND (_value >= minvalue OR minvalue IS NULL)
          AND (_value <= maxvalue OR maxvalue IS NULL)
        LIMIT 1;
    END IF;
 
    RETURN _rangeid;  -- returns NULL if no rule matches at all
END;
$$;


ALTER FUNCTION public.resolve_fb_range(_userid integer, _sensorname character varying, _value double precision) OWNER TO postgres;

